  $('#help').onclick=()=>$('#guide').showModal();$('#close-guide').onclick=$('#guide-play').onclick=()=>{$('#guide').close();canvas.focus();};$('#save').onclick=saveGame;
  $('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=`♪ SOUND ${sound?'ON':'OFF'}`;$('#sound').setAttribute('aria-pressed',String(sound));status('Sound uses simple synthesized effects. Original music is not yet translated.');beep();};let palette=0;$('#palette').onclick=()=>{palette=(palette+1)%3;canvas.className=['','green','gray'][palette];};
  $('#export-save').onclick=()=>{if(!started||battle){status('Start an adventure and finish any battle before exporting.');return;}const out=structuredClone(s);out.seed=random.seed;if(exploreHome)Object.assign(out,exploreHome);download(out,'pokered-save.json');};$('#import-save').onchange=async e=>{try{if(battle)throw Error('Finish the current battle before importing.');const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('Save file is too large.');const imported=loadSave(await file.text());localStorage.setItem(SAVE,JSON.stringify(imported));await startGame(true);status('Imported your saved adventure.');}catch(err){status(err.message);}e.target.value='';};
  populateMaps();$('#map-select').value='PALLET_TOWN';$('#map-search').oninput=e=>populateMaps(e.target.value);$('#travel').onclick=async()=>{if(!started){await startGame();dialogue=null;}if(battle||loading){status('Finish the battle or map transition before traveling.');return;}const id=$('#map-select').value;if(!world.maps[id])return;exploreHome??={map:s.map,x:s.x,y:s.y,dir:s.dir,lastOutdoor:s.lastOutdoor};dialogue=null;menu=null;actions([]);const pos=safePosition(world.maps[id]);await enterMap(id,pos.x,pos.y,'down');status('Exploration mode. Story events and random battles are paused.');canvas.focus();};$('#return-story').onclick=async()=>{if(!exploreHome)return;const home=exploreHome;exploreHome=null;Object.assign(s,home);dialogue=null;menu=null;actions([]);await prepareMap();updatePanels();status('Returned to your story position.');canvas.focus();};
  for(const p of Object.values(db.species).sort((a,b)=>a.dex-b.dex)){const o=document.createElement('option');o.value=p.id;o.textContent=`${String(p.dex).padStart(3,'0')} · ${p.name}`;$('#species-select').append(o);}$('#species-select').onchange=editSpecies;editSpecies();
  $('#apply-mod').onclick=()=>{try{const value=JSON.parse($('#species-editor').value),key=$('#species-select').value;for(const stat of ['hp','attack','defense','speed','special'])if(!Number.isInteger(value.stats?.[stat])||value.stats[stat]<1||value.stats[stat]>255)throw Error('Base stats must be integers from 1 to 255.');const types=new Set(Object.values(original.species).flatMap(p=>p.types));if(!Array.isArray(value.types)||value.types.length<1||value.types.length>2||value.types.some(t=>!types.has(t)))throw Error('Use one or two valid Gen I type names.');if(!Array.isArray(value.startingMoves)||value.startingMoves.length<1||value.startingMoves.length>4||value.startingMoves.some(m=>!db.moves[m]))throw Error('Use one to four valid move IDs.');if(!Array.isArray(value.learnset)||value.learnset.some(m=>!db.moves[m.move]||!Number.isInteger(m.level)||m.level<1||m.level>100))throw Error('Learnset entries need a level from 1–100 and a valid move.');if(!Number.isInteger(value.catchRate)||value.catchRate<1||value.catchRate>255||!Number.isInteger(value.baseExp)||value.baseExp<1||value.baseExp>255)throw Error('Catch rate and base EXP must be integers from 1 to 255.');db.species[key]={...db.species[key],stats:value.stats,types:value.types,startingMoves:value.startingMoves,learnset:value.learnset,catchRate:value.catchRate,baseExp:value.baseExp};storeMods();status(`Saved changes to ${pretty(key)}. They apply to newly created Pokémon.`);}catch(e){status(e.message);}};
  $('#reset-mod').onclick=()=>{const key=$('#species-select').value;db.species[key]=structuredClone(original.species[key]);storeMods();editSpecies();status('Restored original species data.');};$('#add-mon').onclick=()=>{if(!started||battle||s.party.length>=6){status('Start a game, finish any battle, and make room in your party first.');return;}const mon=makeMon(db,$('#species-select').value,10,random);s.party.push(mon);s.caught=[...new Set([...s.caught,mon.species])];s.seen=[...new Set([...s.seen,mon.species])];s.modified=true;note(`Workbench added ${pretty(mon.species)} at level 10.`);saveGame();};
