async function boot(){try{[world,db]=await Promise.all(['data/world.json','data/pokemon.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error(`Could not load ${url}`);return r.json();}));original=structuredClone(db);try{const mods=JSON.parse(localStorage.getItem(MODS)||'{}');for(const [k,v] of Object.entries(mods))if(db.species[k])db.species[k]=v;}catch{}await Promise.all([loadImage(world.font.image),loadImage(world.sprites.SPRITE_RED.image)]);setupUI();$('#data-counts').innerHTML=`<div><b>${Object.keys(world.maps).length}</b><small>MAPS</small></div><div><b>${Object.keys(db.species).length}</b><small>SPECIES</small></div><div><b>${Object.keys(db.moves).length}</b><small>MOVES</small></div>`;const overlay=$('#overlay');overlay.replaceChildren();const title=document.createElement('div');title.className='title-pokemon';title.textContent='POKéMON';overlay.append(title);const sub=document.createElement('h2');sub.textContent='RED VERSION';overlay.append(sub);const art=document.createElement('img');art.src=db.species.CHARIZARD.front;art.className='title-art';art.alt='Charizard';overlay.append(art);const tag=document.createElement('p');tag.textContent='A native browser rewrite. The opening chapter is ready to explore.';overlay.append(tag);let exists=false;try{exists=!!localStorage.getItem(SAVE);}catch{}if(exists){const cont=document.createElement('button');cont.textContent='CONTINUE';cont.className='primary';cont.onclick=()=>startGame(true);overlay.append(cont);}const b=document.createElement('button');b.textContent='NEW GAME';if(!exists)b.className='primary';b.onclick=()=>{if(exists){b.textContent='START FRESH? CLICK AGAIN';b.onclick=()=>startGame();}else startGame();};overlay.append(b);$('#location').textContent='PALLET TOWN';status('Original assets loaded. Start an adventure, or inspect the build notes.');requestAnimationFrame(render);
  // Read-only snapshot for developer verification and future regression tooling.
  window.pokered={snapshot:()=>structuredClone({state:s,battle,dialogue:dialogue?{index:dialogue.index,pages:dialogue.pages}:null,menu:menu?{title:menu.title,index:menu.index,items:menu.items.map(i=>i.label)}:null,exploring:!!exploreHome}),source:world.source};
}catch(error){$('#overlay').textContent='Could not load the game. '+error.message;status(error.message);console.error(error);}}
boot();
